  const updateQty = (id, delta) => setCart(c => c.map(i =>
    i.id === id ? { ...i, qty: Math.max(1, i.qty + delta) } : i
  ));

  const toggleWish = (id) => setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);

