// ===================== PRODUCT CARD =====================
function ProductCard({ p, idx, t, lang, onAdd, onWish, wished, width }) {
  const name = p[`name${lang.toUpperCase()}`];
  const colorLabel = lang === 'en' && p.colorEN ? p.colorEN : p.color;
  const waMsg = encodeURIComponent(
    lang === 'al'
      ? `Përshëndetje SM! 👋 Jam i/e interesuar për: ${name} — €${p.price}. A është ende në dispozicion?`
      : `Hi SM! 👋 I'm interested in: ${name} — €${p.price}. Is it still available?`
  );
  const waUrl = `https://wa.me/38344000000?text=${waMsg}`;
  const badgeMap = {
    new: { al: 'I RI', en: 'NEW', bg: '#111', color: '#FAF9F6' },
    verified: { al: 'VERIFIKUAR', en: 'VERIFIED', bg: '#A8B5A2', color: '#fff' },
    bestseller: { al: 'TOP', en: 'TOP', bg: '#C9A88B', color: '#fff' },
    sale: { al: 'ULJE', en: 'SALE', bg: '#111', color: '#FAF9F6' },
    lowstock: { al: 'PAK MBETUR', en: 'LOW STOCK', bg: '#C9A88B', color: '#fff' },
  };
  const badge = badgeMap[p.badge];

  return (
    <div className="product-card" style={{ width: width || '100%', flexShrink: 0, position: 'relative' }}>
      <div className="img-wrap" style={{
        position: 'relative', aspectRatio: '4/5', background: p.colorHex, marginBottom: 16, overflow: 'hidden',
      }}>
        {/* Real photo overlays the illustration when present; otherwise illustration shows */}
        <div className="product-img" style={{ position: 'absolute', inset: 0 }}>
          <BagIllustration type={p.illustration} accentColor={getAccentColor(p.colorHex)} />
          {p.realPhoto && (
            <img src={p.realPhoto} alt={name}
                 style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
          )}
        </div>

        {/* Badge top-left */}
        {badge && (
          <span style={{
            position: 'absolute', top: 12, left: 12, zIndex: 2,
            background: badge.bg, color: badge.color,
            fontSize: 9, letterSpacing: '.15em', padding: '4px 10px', fontWeight: 500,
            display: 'inline-flex', alignItems: 'center', gap: 4,
            fontFamily: 'Geist, sans-serif',
          }}>
            {p.badge === 'verified' && <Check size={10} strokeWidth={2.5} />}
            {badge[lang]}
          </span>
        )}

        {/* Wishlist top-right */}
        <button onClick={() => onWish(p.id)} aria-label="Wishlist"
                style={{ position: 'absolute', top: 12, right: 12, zIndex: 2,
                         background: 'rgba(250,249,246,.92)', backdropFilter: 'blur(8px)',
                         border: 'none', cursor: 'pointer', width: 32, height: 32, borderRadius: '50%',
                         display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Heart size={14} strokeWidth={1.4} fill={wished ? '#C9A88B' : 'none'} color={wished ? '#C9A88B' : '#111'} />
        </button>

        {/* Quick actions on hover */}
        <div className="quick-actions" style={{
          position: 'absolute', bottom: 12, left: 12, right: 12, zIndex: 2,
          display: 'flex', gap: 8,
        }}>
          <button onClick={() => onAdd(p)} style={{
            flex: 1, background: 'var(--ink)', color: 'var(--bone)', border: 'none', cursor: 'pointer',
            padding: '10px', fontSize: 11, letterSpacing: '.1em', textTransform: 'uppercase', fontFamily: 'inherit',
          }}>
            {t('Shto', 'Add')} +
          </button>
          <a href={waUrl} target="_blank" rel="noopener noreferrer" style={{
            background: '#25D366', color: 'white', padding: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', textDecoration: 'none',
          }} aria-label="WhatsApp order">
            <MessageCircle size={14} strokeWidth={1.6} />
          </a>
        </div>
      </div>

      {/* Card text */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12 }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
            <span className="mono" style={{ fontSize: 10, color: 'var(--smoke)', letterSpacing: '.1em' }}>{String(idx).padStart(2, '0')}</span>
            <span style={{ fontSize: 11, color: 'var(--smoke)' }}>· {colorLabel}</span>
          </div>
          <div className="serif" style={{ fontSize: 16, fontWeight: 500, lineHeight: 1.2 }}>{name}</div>
        </div>
        <div style={{ textAlign: 'right' }}>
          {p.oldPrice && (
            <div className="mono" style={{ fontSize: 11, color: 'var(--smoke)', textDecoration: 'line-through' }}>€{p.oldPrice.toFixed(2)}</div>
          )}
          <div className="mono" style={{ fontSize: 14, fontWeight: 500, color: p.oldPrice ? '#C9A88B' : 'var(--ink)' }}>€{p.price.toFixed(2)}</div>
        </div>
      </div>
    </div>
  );
}

// ===================== ACCENT COLOR HELPER =====================
// Picks ink or bone for line color depending on background luminance.
function getAccentColor(hex) {
  const h = (hex || '#cccccc').replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum > 0.55 ? '#1a1a1a' : '#FAF9F6';
}

// ===================== BAG ILLUSTRATION =====================
// Five distinct editorial line-drawing illustrations, one per bag type.
// Designed to read as a deliberate aesthetic choice — fashion-magazine
// line art — until real product photography is ready to drop in.
function BagIllustration({ type, accentColor = '#1a1a1a', size = '60%' }) {
  const c = accentColor;
  const sw = 1.4; // stroke width
  const common = {
    fill: 'none', stroke: c, strokeWidth: sw,
    strokeLinecap: 'round', strokeLinejoin: 'round',
  };

  const illustrations = {
    // 1. Structured rectangular bag with chain handle and croco texture
    'mini-croco': (
      <svg viewBox="0 0 200 240" width={size} height={size}>
        {/* Chain handle */}
        <path d="M 70 92 Q 70 38 100 38 Q 130 38 130 92" {...common} />
        {/* Subtle chain links */}
        <circle cx="78" cy="56" r="2" {...common} />
        <circle cx="100" cy="40" r="2" {...common} />
        <circle cx="122" cy="56" r="2" {...common} />
        {/* Body */}
        <rect x="50" y="92" width="100" height="118" rx="4" {...common} />
        {/* Top flap line */}
        <path d="M 50 112 L 150 112" {...common} />
        {/* Clasp */}
        <rect x="92" y="106" width="16" height="9" rx="1.5" {...common} />
        {/* Croco texture — small dots */}
        {[
          [68, 138], [82, 144], [96, 138], [110, 144], [124, 138], [138, 144],
          [68, 158], [82, 164], [96, 158], [110, 164], [124, 158], [138, 164],
          [68, 178], [82, 184], [96, 178], [110, 184], [124, 178], [138, 184],
        ].map(([x, y], i) => (
          <circle key={i} cx={x} cy={y} r="1.1" fill={c} stroke="none" opacity="0.55" />
        ))}
      </svg>
    ),

    // 2. Oblong vintage bag, single shoulder strap, round clasp
    'vintage-shoulder': (
      <svg viewBox="0 0 200 240" width={size} height={size}>
        {/* Long shoulder strap */}
        <path d="M 65 96 Q 65 22 100 22 Q 135 22 135 96" {...common} />
        {/* Inner strap line for thickness */}
        <path d="M 70 96 Q 70 28 100 28 Q 130 28 130 96" {...common} opacity="0.35" />
        {/* Body — oblong */}
        <rect x="38" y="96" width="124" height="112" rx="3" {...common} />
        {/* Aged double seam */}
        <line x1="38" y1="108" x2="162" y2="108" {...common} />
        <line x1="38" y1="111" x2="162" y2="111" {...common} opacity="0.4" />
        {/* Round vintage clasp */}
        <circle cx="100" cy="148" r="9" {...common} />
        <circle cx="100" cy="148" r="3" {...common} />
        {/* Tiny stitched corner accent */}
        <line x1="48" y1="200" x2="56" y2="200" {...common} opacity="0.4" />
        <line x1="144" y1="200" x2="152" y2="200" {...common} opacity="0.4" />
      </svg>
    ),

    // 3. Small square bag with diamond quilt pattern, chain crossbody
    'quilted-crossbody': (
      <svg viewBox="0 0 200 240" width={size} height={size}>
        {/* High-arching chain crossbody */}
        <path d="M 62 102 Q 100 22 138 102" {...common} />
        {/* Chain link dots */}
        {[[74, 52], [100, 28], [126, 52]].map(([x, y], i) => (
          <circle key={i} cx={x} cy={y} r="2" {...common} />
        ))}
        {/* Body */}
        <rect x="58" y="102" width="84" height="100" rx="3" {...common} />
        {/* Diamond quilt — diagonals one way */}
        <line x1="78" y1="102" x2="58" y2="122" {...common} opacity="0.4" />
        <line x1="98" y1="102" x2="58" y2="142" {...common} opacity="0.4" />
        <line x1="118" y1="102" x2="58" y2="162" {...common} opacity="0.4" />
        <line x1="138" y1="102" x2="58" y2="182" {...common} opacity="0.4" />
        <line x1="142" y1="122" x2="78" y2="186" {...common} opacity="0.4" />
        <line x1="142" y1="142" x2="98" y2="186" {...common} opacity="0.4" />
        <line x1="142" y1="162" x2="118" y2="184" {...common} opacity="0.4" />
        {/* Diamond quilt — other diagonal */}
        <line x1="58" y1="122" x2="142" y2="122" {...common} opacity="0" />
        <line x1="78" y1="102" x2="142" y2="166" {...common} opacity="0.4" />
        <line x1="58" y1="122" x2="142" y2="186" {...common} opacity="0.4" />
        <line x1="58" y1="142" x2="118" y2="200" {...common} opacity="0.4" />
        <line x1="58" y1="162" x2="98" y2="200" {...common} opacity="0.4" />
        <line x1="58" y1="182" x2="78" y2="202" {...common} opacity="0.4" />
        <line x1="98" y1="102" x2="142" y2="146" {...common} opacity="0.4" />
        <line x1="118" y1="102" x2="142" y2="126" {...common} opacity="0.4" />
        {/* Center clasp */}
        <rect x="92" y="146" width="16" height="8" rx="1" {...common} />
      </svg>
    ),

    // 4. Soft pouch — envelope shape, no handle
    'soft-pouch': (
      <svg viewBox="0 0 200 240" width={size} height={size}>
        {/* Optional small wrist loop */}
        <path d="M 100 78 Q 100 70 108 70 Q 116 70 116 80" {...common} />
        {/* Body */}
        <rect x="34" y="98" width="132" height="104" rx="3" {...common} />
        {/* Envelope flap */}
        <path d="M 34 98 L 100 152 L 166 98" {...common} />
        {/* Inner flap shadow line */}
        <path d="M 38 102 L 100 148 L 162 102" {...common} opacity="0.3" />
        {/* Small clasp dot at flap tip */}
        <circle cx="100" cy="152" r="3" {...common} />
        {/* Corner stitch accents */}
        <line x1="44" y1="194" x2="52" y2="194" {...common} opacity="0.4" />
        <line x1="148" y1="194" x2="156" y2="194" {...common} opacity="0.4" />
      </svg>
    ),

    // 5. Boxy bag with prominent rounded top handle
    'top-handle': (
      <svg viewBox="0 0 200 240" width={size} height={size}>
        {/* Rounded top handle */}
        <path d="M 78 112 Q 78 60 100 60 Q 122 60 122 112" {...common} />
        {/* Inner handle line */}
        <path d="M 84 112 Q 84 66 100 66 Q 116 66 116 112" {...common} opacity="0.35" />
        {/* Body — boxy */}
        <rect x="52" y="112" width="96" height="100" rx="3" {...common} />
        {/* Top flap line */}
        <line x1="52" y1="128" x2="148" y2="128" {...common} />
        {/* Small clasp at top center */}
        <rect x="94" y="122" width="12" height="7" rx="1" {...common} />
        {/* Small base dot accent (foot) */}
        <line x1="56" y1="208" x2="64" y2="208" {...common} opacity="0.4" />
        <line x1="136" y1="208" x2="144" y2="208" {...common} opacity="0.4" />
      </svg>
    ),
  };

  return (
    <div style={{
      width: '100%', height: '100%', display: 'flex',
      alignItems: 'center', justifyContent: 'center',
    }}>
      {illustrations[type] || illustrations['top-handle']}
    </div>
  );
}

